package com.nimbusbill.customer.controller;
import com.nimbusbill.customer.dto.ProductRequest; import com.nimbusbill.customer.entity.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import tools.jackson.databind.ObjectMapper; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ProductControllerTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json;
 @Test void productLifecycle() throws Exception {String code="PROD_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();ProductRequest r=new ProductRequest(code,"Test Product","API test",PricingUnit.FIXED,BigDecimal.ONE,BigDecimal.TEN,true,ProductStatus.DRAFT,LocalDate.now(),null);String body=mvc.perform(post("/api/v1/products").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(r))).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("DRAFT")).andReturn().getResponse().getContentAsString();String id=json.readTree(body).get("id").asText();mvc.perform(get("/api/v1/products").param("status","DRAFT")).andExpect(status().isOk()).andExpect(jsonPath("$[0].productCode").value(code));mvc.perform(post("/api/v1/products/{id}/activate",id)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ACTIVE"));mvc.perform(post("/api/v1/products/{id}/deactivate",id)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("INACTIVE"));}
 @Test void rejectsInvalidFeeRange(){ProductRequest r=new ProductRequest("INVALID_RANGE","Invalid","test",PricingUnit.FIXED,BigDecimal.TEN,BigDecimal.ONE,true,ProductStatus.DRAFT,LocalDate.now(),null);try{mvc.perform(post("/api/v1/products").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(r))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.message").value("minimumFee cannot exceed maximumFee"));}catch(Exception e){throw new RuntimeException(e);}}
}
